    "status": "Ready to Submit",
    "fileName": "texas_bar_foundation_legal_clinic.md",
    "filePath": "data/acbf/grants/texas_bar_foundation_legal_clinic.md",
    "title": "Grant Application: Texas Bar Foundation – Legal Services & Access to Justice",
